CREATE TABLE IF NOT EXISTS mci_zone (id CHAR(36) PRIMARY KEY, name VARCHAR(60) NOT NULL, sort_order SMALLINT NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY mci_zone_name_unique (name)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mci_triage_level (id CHAR(36) PRIMARY KEY, name VARCHAR(40) NOT NULL, description VARCHAR(120) NOT NULL DEFAULT '', color_hex CHAR(7) NOT NULL, sort_order SMALLINT NOT NULL, is_deceased TINYINT(1) NOT NULL DEFAULT 0, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY mci_triage_level_name_unique (name)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mci_patient_status (id CHAR(36) PRIMARY KEY, name VARCHAR(60) NOT NULL, sort_order SMALLINT NOT NULL, is_deceased TINYINT(1) NOT NULL DEFAULT 0, needs_destination TINYINT(1) NOT NULL DEFAULT 0, is_discharged TINYINT(1) NOT NULL DEFAULT 0, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY mci_patient_status_name_unique (name)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mci_profession (id CHAR(36) PRIMARY KEY, name VARCHAR(80) NOT NULL, sort_order SMALLINT NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY mci_profession_name_unique (name)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mci_profession_position (profession_id CHAR(36) NOT NULL, position_id CHAR(36) NOT NULL, PRIMARY KEY (profession_id, position_id), UNIQUE KEY mci_profession_position_unique (position_id), CONSTRAINT mci_profession_position_profession_fk FOREIGN KEY (profession_id) REFERENCES mci_profession(id), CONSTRAINT mci_profession_position_position_fk FOREIGN KEY (position_id) REFERENCES hr_position(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mci_assignment_rule (profession_id CHAR(36) PRIMARY KEY, zone_id CHAR(36) NULL, updated_at DATETIME NOT NULL, CONSTRAINT mci_assignment_rule_profession_fk FOREIGN KEY (profession_id) REFERENCES mci_profession(id), CONSTRAINT mci_assignment_rule_zone_fk FOREIGN KEY (zone_id) REFERENCES mci_zone(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mci_setting (setting_key VARCHAR(64) PRIMARY KEY, setting_value VARCHAR(255) NOT NULL, updated_at DATETIME NOT NULL) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mci_incident_lock (id TINYINT PRIMARY KEY) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mci_incident (id CHAR(36) PRIMARY KEY, title VARCHAR(200) NOT NULL, kind VARCHAR(8) NOT NULL, status VARCHAR(8) NOT NULL, location VARCHAR(300) NOT NULL DEFAULT '', occurred_at DATETIME NOT NULL, opened_by CHAR(36) NOT NULL, opened_at DATETIME NOT NULL, closed_by CHAR(36) NULL, closed_at DATETIME NULL, patient_seq INT NOT NULL DEFAULT 0, updated_at DATETIME NULL, KEY mci_incident_status_index (status, opened_at), CONSTRAINT mci_incident_opened_by_fk FOREIGN KEY (opened_by) REFERENCES person(id), CONSTRAINT mci_incident_closed_by_fk FOREIGN KEY (closed_by) REFERENCES person(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mci_responder (id CHAR(36) PRIMARY KEY, incident_id CHAR(36) NOT NULL, person_id CHAR(36) NOT NULL, profession_id CHAR(36) NULL, zone_id CHAR(36) NULL, command_role VARCHAR(12) NOT NULL, checked_in_at DATETIME NOT NULL, checked_out_at DATETIME NULL, checked_out_by CHAR(36) NULL, active_key TINYINT AS (IF(checked_out_at IS NULL, 1, NULL)) PERSISTENT, UNIQUE KEY mci_responder_active (incident_id, person_id, active_key), KEY mci_responder_zone_index (incident_id, zone_id), CONSTRAINT mci_responder_incident_fk FOREIGN KEY (incident_id) REFERENCES mci_incident(id), CONSTRAINT mci_responder_person_fk FOREIGN KEY (person_id) REFERENCES person(id), CONSTRAINT mci_responder_profession_fk FOREIGN KEY (profession_id) REFERENCES mci_profession(id), CONSTRAINT mci_responder_zone_fk FOREIGN KEY (zone_id) REFERENCES mci_zone(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mci_patient (id CHAR(36) PRIMARY KEY, incident_id CHAR(36) NOT NULL, tag_no INT NOT NULL, triage_level_id CHAR(36) NOT NULL, status_id CHAR(36) NOT NULL, zone_id CHAR(36) NOT NULL, destination_hospital VARCHAR(200) NOT NULL DEFAULT '', first_name VARCHAR(120) NOT NULL DEFAULT '', last_name VARCHAR(120) NOT NULL DEFAULT '', gender VARCHAR(8) NOT NULL DEFAULT 'UNKNOWN', age_estimate SMALLINT NULL, hn VARCHAR(20) NOT NULL DEFAULT '', public_hidden TINYINT(1) NOT NULL DEFAULT 0, created_by CHAR(36) NOT NULL, created_at DATETIME NOT NULL, updated_by CHAR(36) NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY mci_patient_tag (incident_id, tag_no), KEY mci_patient_zone_index (incident_id, zone_id), CONSTRAINT mci_patient_incident_fk FOREIGN KEY (incident_id) REFERENCES mci_incident(id), CONSTRAINT mci_patient_triage_fk FOREIGN KEY (triage_level_id) REFERENCES mci_triage_level(id), CONSTRAINT mci_patient_status_fk FOREIGN KEY (status_id) REFERENCES mci_patient_status(id), CONSTRAINT mci_patient_zone_fk FOREIGN KEY (zone_id) REFERENCES mci_zone(id)) DEFAULT CHARSET=utf8mb4;
